WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (593, '1', 'ASK 593: Haiku is out of the debate engine in full (judge, alternate, debater, dashboard list)',
  $t$Haiku is removed from the debate engine in full, as the operator ordered: no panel judge, no alternate and no debater, and not offered by the dashboard. (Ruling rows 518 and 519; W4's build notes, head.)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write ASK 593" at 01:26 CST 2026-11-24 in W4's thread, with no run live (Wall 11442; audit 41278). Engine moMxiV4Irg1uRBZN 9bec145c to a17c7a7b-9705-4e39-ad91-608211681c9b, 422 nodes, 17 changed, by removals only; child MqQHRl7mQQ0z8QdT 2d5bdc94 to e9ddab5e-40ae-410f-b0a2-059799ac4d90 (Shared Library). LIB a5b27df14d596da7, MAP e6f0341b87c6190c. Then the migration mig593.sql. What is live: no engine or child node holds the word haiku. Init Seats: haiku is out of ORDER0, __ALT, ENG, FAM_PANEL and the call-family map; the rule that moved haiku to the end after the first three free seats is removed; the single judge's filter keeps "not sonnet" only. Accept Build: out of ORDER and ENG_SEAT. Resolve Seats, Build Synthesis, Build Independent Verdict and Build Diagnostic Prompt: out of the call-family map. The direct Anthropic id form in Resolve Seats and D1 to D4 and C1 to C4 Build reads claude-(opus|sonnet|fable|mythos). Format Markdown and Failure Salvage no longer name it. The Shared Library's cure-note model list loses anthropic/claude-haiku-5.5. Database: dash_debaters has no haiku row (md5 4a16cddc), so the dashboard does not offer it and dash_launch_odv1 refuses it; odv1_record_panel_substitution's seat list has no haiku (md5 1b1c2188); the model_config row haiku is kept, active false. A launch naming haiku is refused at Init Seats: 'defender engine "haiku" is not one of [claude, chatgpt, gemini, grok, mimo, opus, glm, qwen4max, spark, sol62, deepseek]'. Left as they are (W1 R1, Wall 11439): the display-order lists of dash_odv1_debates and dash_odv1_judges, which sort past judgments; the comment in odv1_record_panel_alternates; past records. Effect on the line-up (Init Seats replayed on 270 cases): haiku is seated in none; no pair that ran before is refused; 78 cases change, each one where haiku sat; four pairs (chatgpt or sol62 against gemini, both ways) keep the panel spark, qwen4max and sonnet with no reserve and no alternate. W1 readback MATCH (Wall 11443): engine a17c7a7b equals target_engine_593.json and W1's rebuild, 0 node differences, 0 nodes hold haiku; child e9ddab5e the same; dash_debaters and odv1_record_panel_substitution differ from their pre-write sources by the haiku word only; model_config haiku active false. IN PART, because no run has executed on a17c7a7b: the removal is shown by the readback and the offline replay, not by a run. The path: the operator's two messages (01:15 and 01:16 CST, W3 thread); W3's reading posted at Wall 11432 and 11433; the coordinator numbered it 593; W4's build rev 0 (Wall 11437); W1 PASS (Wall 11439); the press; the write (Wall 11442); the readback (Wall 11443). Found and not changed (scope rule; W1 R2): odv1_record_panel_substitution's seat list has never held qwen4max, and Init Seats makes qwen4max the reserve in 2 pairs after this write (16 before); a reserve used there would raise at its record. It is W4's separate question to the operator (ASK 594 on W4's card). Consequence for other work: ASK 590 must be re-cut on a17c7a7b before its write; the ASK 591 table is seeded without haiku (plan rev 4, Wall 11445).$t$,
  '11432, 11433, 11437, 11439, 11442, 11443',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$01:15 CST 2026-11-24, W3 thread (ruling row 518): "remove Haiku from lineup". 01:16 CST 2026-11-24, W3 thread (ruling row 519): "remove from debate engine in full". His press at 01:26 CST 2026-11-24 in W4's thread: "Write ASK 593" (Wall 11442).$t$::text),
  $j${"answer": "Write ASK 593", "source": "Wall 11442; audit 41278", "thread": "W4", "press_time": "01:26 CST 2026-11-24", "question": "not in the record W3 read (the card is in W4's thread); the card text is ask593/w4/card593.md 6ef05e92"}$j$::jsonb,
  'W4',
  $j${"md5": "93e0315b", "path": "ask593/w4/build593_notes.md", "commit": "0ae0d40f", "note": "build notes rev 0; no separate plan file: the operator's order was a direct ruling and W4 built to it", "source": "md5sum by W3; Wall 11437, 11439"}$j$::jsonb,
  $j$[{"md5": "046ac782", "path": "ask593/w4/build/target_engine_593.json", "note": "the engine as built on live 9bec145c; graded and read back", "source": "md5sum by W3; Wall 11439, 11443"}, {"md5": "1c741179", "path": "ask593/w4/build/target_child_593.json", "note": "the child as built on live 2d5bdc94", "source": "md5sum by W3; Wall 11439, 11443"}, {"md5": "3403ced4", "path": "ask593/w4/build/target_engine_593_on590.json", "note": "second target, cut on the ASK 590 target; not written", "source": "md5sum by W3"}, {"md5": "53a33b29", "path": "ask593/w4/build/target_child_593_on590.json", "note": "second target, child; not written", "source": "md5sum by W3"}, {"md5": "044f41e2", "path": "ask593/w4/build/build593.cjs", "note": "the build script", "source": "md5sum by W3"}, {"md5": "8c705c2e", "path": "ask593/w4/build/t593.cjs", "note": "the test, 12 cases over a 270-case replay", "source": "md5sum by W3"}, {"md5": "79e9e1de", "path": "ask593/w4/build/out_t593.txt", "note": "test output; the same md5 as write/t593_at_write.txt", "source": "md5sum by W3"}, {"md5": "a0b2e27f", "path": "ask593/w4/build/mig593.sql", "note": "the migration, applied after the engine", "source": "md5sum by W3"}, {"md5": "8ec14a07", "path": "ask593/w4/build/revert593.sql", "note": "the database revert", "source": "md5sum by W3"}, {"md5": "101d1b91", "path": "ask593/w4/write/prewrite_eng593.json", "note": "fresh fetch before the write; the same md5 as build/base_eng.json", "source": "md5sum by W3"}, {"md5": "d72f33f9", "path": "ask593/w4/write/prewrite_child593.json", "note": "fresh fetch before the write, child; the same md5 as build/base_child.json", "source": "md5sum by W3"}, {"md5": "09eb6f16", "path": "ask593/w4/write/prewrite_dash_debaters.sql", "note": "dash_debaters as it stood before the write", "source": "md5sum by W3"}, {"md5": "2299aa0b", "path": "ask593/w4/write/put_eng593.json", "note": "PUT body, engine", "source": "md5sum by W3"}, {"md5": "9364397d", "path": "ask593/w4/write/p