  $j${"copy": "restore the engine and the child together from ask593/w4/write/revert_eng593.json 3bb19d4b and revert_child593.json 51fd19c5 (to 9bec145c and 2d5bdc94), run ask593/w4/build/revert593.sql 8ec14a07, and restore dash_debaters from write/prewrite_dash_debaters.sql 09eb6f16", "path": "ask593/w4/write/revert_eng593.json; ask593/w4/write/revert_child593.json; ask593/w4/build/revert593.sql; ask593/w4/write/prewrite_dash_debaters.sql", "source": "Wall 11442 item 4; build593_notes.md section 4; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (build rev 0: W1's rebuild equals both target pairs, 0 node differences; no haiku in the rebuilt engine; t593 12 PASS; both recorder functions read)", "wall_id": 11439, "md5_graded": "046ac782", "verdict_norm": "PASS", "source": "Wall 11439 head and \"Checked\"; the md5 is md5sum by W3 on ask593/w4/build/target_engine_593.json, the engine target of the graded commit 0ae0d40f"}, {"seat": "W1", "verdict": "PASS (the child target, the same grade)", "wall_id": 11439, "md5_graded": "1c741179", "verdict_norm": "PASS", "source": "Wall 11439 \"my rebuild equals both target pairs\"; the md5 is md5sum by W3 on ask593/w4/build/target_child_593.json"}]$j$::jsonb,
  ARRAY['046ac782','1c741179'], '[41278]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "before": "9bec145c, 422 nodes", "after": "a17c7a7b-9705-4e39-ad91-608211681c9b, 422 nodes, 17 changed"}, {"kind": "n8n workflow", "name": "child MqQHRl7mQQ0z8QdT", "before": "2d5bdc94", "after": "e9ddab5e-40ae-410f-b0a2-059799ac4d90, 156 nodes, Shared Library only"}, {"kind": "n8n nodes, changed (17 engine)", "name": "Init Seats, Accept Build, Resolve Seats, Build Synthesis, Build Independent Verdict, Build Diagnostic Prompt, D1 to D4 Build, C1 to C4 Build, Format Markdown, Failure Salvage, Shared Library", "before": "as in 9bec145c", "after": "no node holds the word haiku (build593_notes.md section 1; the list of 17 is W3's count of the names the notes give)"}, {"kind": "library", "name": "Shared Library, engine and child", "before": "LIB 14d848a99adaf445, MAP 3675b0b63c7c05f7 (row 159)", "after": "LIB a5b27df14d596da7, MAP e6f0341b87c6190c"}, {"kind": "database function", "name": "dash_debaters", "before": "functiondef source md5 1fb7adfe (W1), with the row (6,'haiku','Haiku','haiku')", "after": "md5 4a16cddc, no haiku row"}, {"kind": "database function", "name": "odv1_record_panel_substitution", "before": "source md5 91083e19 (W1), v_seats with haiku", "after": "md5 1b1c2188, v_seats without haiku; security definer and grants kept"}, {"kind": "table row", "name": "model_config seat haiku", "before": "active true", "after": "active false, with a note; the row is kept"}]$j$::jsonb,
  $j$[{"name": "t593.cjs, 12 cases over a 270-case replay of Init Seats (11 debaters, every ordered pair, with no fault-ledger move and with sol or gemini moved)", "result": "12 PASS; haiku seated in 0 cases; 0 pairs refused that ran before; 78 cases change; rerun by W1 and at the write", "source": "Wall 11437 item 3; 11439; 11442 item 1; build593_notes.md section 3"}, {"name": "Library Check pair", "result": "PASSES: LIB a5b27df14d596da7, MAP e6f0341b87c6190c", "source": "Wall 11442 item 1"}, {"name": "haiku scan", "result": "0 nodes of the engine and 0 of the child hold haiku (W1's own fetch); the three called sub-workflows hold none (W4)", "source": "Wall 11443; 11442 item 3"}, {"name": "Seat-change rule (W1): both recorder functions read", "result": "odv1_record_panel_alternates admits by model_config active, so an inactive haiku is refused; odv1_record_panel_substitution: only the list word changes", "source": "Wall 11439"}]$j$::jsonb,
  $j$[{"seat": "W1", "wall_id": 11443, "result": "MATCH (W1's own fetch: engine a17c7a7b, 422 nodes, equals target_engine_593.json and W1's rebuild, 0 node differences, connections equal, 0 nodes hold haiku; child e9ddab5e, 156 nodes, the same; dash_debaters md5 4a16cddc, putting the haiku row back gives the pre-write source 1fb7adfe exactly; odv1_record_panel_substitution md5 1b1c2188, putting haiku back gives 91083e19 exactly; model_config haiku active false)"}]$j$::jsonb,
  $j${"case": "UNEXERCISED. No run has executed on engine a17c7a7b. EXPECT on the first run: the Init Seats output and the Accept Build seat list hold no haiku; no judgment row names a haiku model; in the usual debate the panel is terra, sol and 6.2 sol and the reserve is gemini.", "source": "Wall 11442; build593_notes.md section 3; the last clause (reserve gemini) is W3's reading of the live order chatgpt, sol, sol62, gemini, spark, qwen4max, argon, sonnet, not a statement of W4's"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "not yet at the draft of this row: version 282 still names haiku as judge, alternate and debater in parts 02.0, 04.0, 10.0 and 17.0; W3's entry draft is manual1123/w3/a593/em_pairs_593_draft1.json, for W1's grade and the operator's card"}$j$::jsonb,
  'read back', $j$[11432, 11433, 11437, 11439, 11442, 11443]$j$::jsonb)
RETURNING id)
